  "heroglyph.flow.dogCharacter.slide.guardian.desc": "把家门当成冥界之门来守。先叫再说，从来不问。",
  "heroglyph.flow.dogCharacter.slide.player.desc": "为了多扔一次球，灵魂都能卖。最大的快乐：心爱的玩具。",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "没有关机键，不需要电池。最常被问：你家狗嗑了什么？",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "自带世界和规矩的现代海盗。选择性耳聋是它的第一法则。",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "狗分两种——其中一种会被错认成鱼。湿漉漉的毛：100% 幸福。",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "吃就是使命。全力以赴，毫不犹豫——你没吃完的，它也包了。",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "在它眼里没有陌生人。每次见到邮递员，都像重逢失散多年的灵魂伴侣。每一次。",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "已练成上古绝学：优雅地什么都不做。",
