  "notFound.returnHome": "返回首页",
  "about.origin.title": "起源<br />故事",
  "about.origin.sub": "滑动并阅读",
  "about.origin.skip": "或跳过",
  "about.crawl.intro": "十年前，在欧洲腹地的一家收容所里……",
  "about.crawl.episode": "第一章",
  "about.crawl.faith": "新的信仰",
  "about.crawl.p1": "2016 年，八只黑色小狗被装在一个纸箱里丢弃，送到了收容所。七只找到了家，最大的那只没有人想要——它等待了整整一年。它的名字叫 Hekthor。",
  "about.crawl.p2": "有一天，一对夫妇来到收容所，想领养一只名叫 Sindy 的白色小母狗。恰好那时，Hekthor 在 Sindy 的笼子里——他自己的笼子正在打扫。那个只是陪伴而来、从未想过养狗的男人，对这只他第一次见到的黑狗一见钟情。",
  "about.crawl.p3": "一周后，两人在一起了，一段美好的故事就此开始。这个男人的整个人生都改变了，而他最终明白了一件事：只有真正拥有一只狗、知道狗的爱是什么感觉的人，才能真正帮助那些需要帮助的狗。",
  "about.crawl.p4": "于是，Heroglyph 诞生了——一个旨在将世界各地的爱犬人士团结成有史以来最大社群的符号。这个社群将为我们自己、为我们的狗，以及为子孙后代而站出来——为那些敢于承认狗不只是动物，而是让我们成为更好的人的存在的人们而建立。",
  "about.crawl.p5": "现在，通往第一个里程碑的旅程开始了——创造 1,000,000 枚 Heroglyph。你也可以成为其中一部分。因为只有那些疯狂到相信自己能改变世界的人，才能真的做到。",
  "about.crawl.p6": "我们信仰狗。",
  "about.timeline.heading": "DOGYPT 的故事",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "收容所",
  "about.milestone.1.title": "收容所里的瑰宝",
  "about.milestone.1.body": "一只没有人想要的黑狗在收容所的围栏后等待。他的名字成为了 Hekthor。领养他不是救援——而是一切的开始。",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "羁绊",
  "about.milestone.2.title": "永恒的羁绊",
  "about.milestone.2.body": "他在我人生最艰难的时期默默陪伴，一句话都没说。每一位爱犬人士都明白这一点——恰好在你快要倒下的时候，是他们托住了你。",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "旅程",
  "about.milestone.3.title": "那段路，变成了一本书",
  "about.milestone.3.body": "我们一起徒步穿越斯洛伐克——42 天，800 公里，一个无声的承诺。那条路成为了一本书：《Cesta s Hrdinom》——与英雄同行。",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "命名",
  "about.milestone.4.title": "爱犬人士之国",
  "about.milestone.4.body": "金字塔、神秘主义、埃及永恒的荣耀——几千年来令人类着迷。将其与对狗无尽的爱结合，便得到了 DOGYPT。2022 年迪拜世博会上，我身着法老装束，将这个想法镌刻成形。",
  "about.milestone.5.year": "现在",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "旅程从你开始",
  "about.milestone.5.body": "DOGYPT 是一场运动，属于每一个被狗改变了人生的人。建立在地球上最古老、最真实的羁绊之上。Hekthor 是第 1 号创始人。你是下一个。",
  "about.outro.quoteLead": "它从来都不只是",
  "about.outro.quoteTail": "\"一只狗。\"",
  "about.outro.body": "你已经知道那种感觉——狗不是你拥有的东西，而是<strong>你深爱的某个人</strong>。现在想象一下，这份爱被组织起来、彼此连结，<strong>强大到足以改变一切。</strong>这就是 <strong>DOGYPT</strong> 存在的原因。",
  "about.outro.name1": "Matej",
  "about.outro.and": "和",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "成为多吉普特人",
  "about.reel.prev": "上一张照片",
  "about.reel.next": "下一张照片",
  "religion.hook.number": "12",
  "religion.hook.billion": "亿",
  "religion.hook.people": "人",
