  "religion.hook.bow": "向牛跪拜",
  "religion.hook.doglovers": "爱犬人士呢？",
  "religion.hook.worship": "让我们膜拜我们的狗吧。",
  "religion.cta": "成为多吉普特人",
  "religion.aria.question": "那个问题",
  "religion.aria.preamble": "序言",
  "religion.aria.sacredIndex": "神圣索引",
  "religion.aria.scrollDown": "向下滚动",
  "religion.preamble.headlineGrad": "信犬",
  "religion.preamble.headlineLine": "不渝",
  "religion.preamble.text": "我们，爱犬人士之国——深知地球上每一只狗<strong>无尽的忠诚</strong>、<strong>真挚的爱</strong>与<strong>纯洁的灵魂</strong>——为了提升狗在人类社会中的地位，为它们建立一个<strong>社群</strong>，<strong>改善</strong>它们的生活，并<strong>改写</strong>每一只需要帮助的狗的命运，特为自己制定本宪法。",
  "religion.preamble.oath": "犬群誓约",
  "religion.bookTitle": "爱犬人士的\"圣经\"",
  "religion.book.sealAlt": "多吉普特人印章",
  "religion.book.titleThe": "The",
  "religion.book.titleBrand": "Dogypt",
