  "religion.book.trust": "信犬不渝",
  "religion.book.sub": "每位爱犬人士成为多吉普特人的必读之书。",
  "religion.book.cta1.kicker": "踏上征途",
  "religion.book.cta1.head": "加入<br />犬教",
