  "nav.wall": "WALL",
  "nav.vision": "愿景",
  "nav.religion": "宗教",
  "nav.about": "关于我们",
  "nav.login": "登录",
  "wall.hero.taglineLead": "那个",
  "wall.hero.taglineGod": "狗是神。",
  "wall.hero.cta": "成为多吉普特人",
  "wall.hero.total": "1,000,000",
  "wall.hero.dogs": "只狗",
  "wall.hektor.msg": "Hekthor，你是我最伟大的英雄，最好的朋友，忠诚的伙伴，毫不留情的导师——你是我此生最美的故事。因为你，我创立了一个狗的宗教，也明白了我的爱并没有什么特别——每一个曾经爱过狗的人，心里感受到的都是同样的情感。谢谢你陪我度过最美好的一生。我爱你。",
  "wall.info.title": "1,000,000 只狗。<br/>我们能做到吗？",
  "wall.info.body": "DOGYPT 是爱犬人士的运动。每只狗都获得一枚独一无二的 Heroglyph——在全球犬群中永久占据一席之地。我们正在收集一百万个英雄。成为第一批。",
