  "heroglyph.sales.transparency.footer": "每一欧元都公开可见，供每一位成员查看。你并非付钱给一家公司——你在供养这个族群。",
  "entry.declare.eyebrow": "我在此宣告",
  "entry.title": "信犬不渝",
  "entry.subtitle": "这不是玩笑。每一个严肃的宗教都必须宣告这些。",
  "entry.criteria.theology.title": "神学",
  "entry.criteria.theology.body": "最好的朋友、守护者、导师，每一场冒险中的伙伴。狗给予无条件的爱——与它并肩同行，让我们更有人性。",
  "entry.criteria.canon.title": "圣典",
  "entry.criteria.canon.body": "每一种信仰都有经典。我们的是 DOGMA：我们与狗的羁绊，写成十二个篇章，可在 dogma.dogypt.com 免费阅读。",
  "entry.criteria.community.title": "社群",
  "entry.criteria.community.body": "我们是心怀使命的爱犬人士。独自一人，每个人能改变的很少——齐心协力，我们的力量没有极限。",
  "entry.criteria.symbol.title": "符号",
  "entry.criteria.symbol.body": "每一种信仰都有它的标记。我们的是 Heroglyph：为每一只狗铸造的独一无二的神圣印记，在任何语言、任何地方都能被读懂。",
  "entry.criteria.ritual.title": "仪式",
  "entry.criteria.ritual.body": "散步。每日的疗愈，让身与心保持良好状态——灵魂亦然。这是我们无需被提醒就早已恪守的最古老的仪式。",
  "entry.criteria.vision.title": "愿景",
  "entry.criteria.vision.body": "提升人与狗之间的羁绊——并为每一只狗应得的尊重与更好的生活而奋斗。",
  "entry.criteria.offerings.title": "供奉",
  "entry.criteria.offerings.note": "（一份象征性的敬献）",
  "entry.criteria.offerings.pill": "€11 · 一次性",
  "entry.criteria.offerings.tag": "100% 透明",
  "entry.criteria.offerings.body": "€11，仅此一次。一份象征性的供奉——每一笔收入与每一笔支出，都记录在向所有人公开的账本上。这是维系我们存续的能量。",
  "entry.criteria.legitimacy.title": "正统性",
  "entry.criteria.legitimacy.pill": "还剩 {count} 位成员",
  "entry.criteria.legitimacy.body": "一千位创始者，我们便足够强大，得以注册为一个法律必须承认的国度。最后的印记——唯有你能抵达。",
