  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. 犬群内部：其他成员能看到什么",
  "privacy.s12.body": "第 3 条描述的是公开的 GodsGrid。在犬群内部——仅限成员的区域——其他已登录的成员能看到更多内容：你的名字、你的多吉普特编号、你的狗的名字和照片、你为狗填写的各项属性、你记录或公布的出游、你的评分和评论，以及你写在个人主页上的任何内容。他们看不到你的电子邮箱、邮寄地址、付款信息，也看不到你与其他人的私信。当你把一次出游设为公开时，路线、日期和你的狗就会对所有成员可见，这样他们就能申请加入——这就是「公布」的含义。你设为私密的出游，只有你和已经同行的人能看到。这两者如何选择由你决定，并且可以随时更改。",
  "privacy.s13.title": "13. 消息与举报",
  "privacy.s13.body": "成员之间的私信保存在我们的数据库（Supabase）中，这样对话才能在不同登录之间保留下来。法律依据：GDPR 第 6 条第 1 款 (b) 项——这些私信是你已付费获得的会员资格的一部分。我们不会定期查看私信，也绝不会把它们用于广告或用户画像。只有在私信被举报、我们正在调查具体的滥用或安全事件，或法律要求时，我们才会打开对话查看。举报会保存你选择的理由、你填写的（可选）说明，以及对被举报内容的引用——而不是另存一份副本。屏蔽功能保存为一对成员标识符。如果你删除账号，你的消息也会一起消失；但对方会话中的那份副本会保留，显示来自「已移除的成员」，因为那段对话同样属于对方。",
  "terms.s12.title": "12. 你发布的内容",
  "terms.s12.body": "除了你的 HEROGLYPH，你还可以在犬群内部发布内容：出游照片、路线和地点、出游描述、评分、评论和提问，以及你写在个人主页上的任何内容。当你把某次出游标记为「已走过」时，其他成员会看到你的名字，以及和你一起走这段路的狗。你发布的一切内容，所有权仍然归你。但通过发布，你授予 DOGYPT s.r.o. 一项全球性、免版税、非排他性的许可，允许其出于运营和推广本服务的目的保存、展示和改编该内容——例如在地图上、出游列表中或分享卡片上展示你的出游照片。该许可在内容留存于本服务期间持续有效；删除内容或账号即终止许可，但备份会按其正常周期到期。我们不会出售你的内容，也不会将其许可给任何其他人用于他们自己的用途。只发布你有权发布的内容——这也包括他人拍摄的照片，以及照片中可被辨认出来的人物。",
  "terms.s13.title": "13. 成员之间的消息",
  "terms.s13.body": "成员之间可以直接互相写信。消息在参与者之间是私密的——我们不会定期查看，也绝不会把它们用于广告。消息保存在我们的服务器上，这样你回来时对话依然还在；我们只会在以下三种情况下查看对话：有人举报、我们正在调查具体的滥用或安全事件，或法律要求这样做。你可以随时屏蔽其他成员；屏蔽立即生效，并且是双向的。对待消息请像对待任何一次网上对话一样——不要发送付款信息、密码，或任何你不想被保存下来的文件。",
  "terms.s14.title": "14. 举报与管理",
  "terms.s14.body": "个人主页、出游和对话都可以被举报。举报会发送给我们，由真人查看——目前就是创始人 Matej Stacho。我们的目标是在 7 天内处理每一条举报。根据调查结果，我们可能什么都不做、移除内容、警告该成员、限制其可发布的内容，或关闭其账号。如果我们对你的内容采取了处理措施，会通过邮件告知你原因，你可以回复并提出异议。我们也可能在内容违反第 7 条时主动将其移除。故意或反复的滥用行为——骚扰、垃圾信息、虚假出游、涉及未成年人的内容——将直接导致账号关闭，不再另行警告。",
