  "pack.cal.life.tgtPre": "目标：",
  "pack.cal.life.tgtBody": "整体护理最多能额外延长五年——保持体态精瘦、在野外活动、照顾牙齿、保证睡眠，以及尽量少用不必要的药物。",
  "pack.cal.life.tgtSrc": "这只是一个粗略的估算，不是承诺。其中只有一项是真正被测量过的：单靠保持精瘦就让拉布拉多多活了 1.8 年（Purina Life Span Study, JAVMA 2002）。",
  "pack.cal.life.intro": "下面是你的狗一生的全貌，以方块呈现。一个方块 = 一周，一行 = 一年。一方面让人有点不安，另一方面也正是这种提醒：要珍惜每一个当下，别再拖延。",
