  "pack.cal.life.recSince": "自 {year} 年起",
  "pack.cal.life.tip.weight.title": "保持精瘦是唯一被证实有效的方法",
  "pack.cal.life.tip.weight.body": "在所有能为狗做的事里，有一件对寿命的证据最为确凿：别让它变胖。精瘦的狗和稍微超重的狗之间的差距，是以年计算的，不是以月计算的。你应该能在不用力按压的情况下摸到它的肋骨。",
  "pack.cal.life.tip.move.title": "在真实地形上活动，不是绕街区一圈",
  "pack.cal.life.tip.move.body": "不平整的地面能让关节、肌肉和大脑都保持活跃。你记录的每一次出游，都会在这张网格上变成一个深色的星期——而深色星期正是你真正能够影响的那部分。",
  "pack.cal.life.tip.food.title": "狗能认出是食物的食物",
  "pack.cal.life.tip.food.body": "原材料到饭碗之间的步骤越少，中途能出问题的地方就越少。狗粮不是罪过，但它也算不上一份正餐——它是一种捷径。",
  "pack.cal.life.tip.chem.title": "只有真正需要的时候才用药",
  "pack.cal.life.tip.chem.body": "全年驱虫、为了方便而用麻醉、「以防万一」的抗生素——这些都是需要权衡的决定，不是常规操作。每一次都问问自己：如果不这样做会怎样？只要答案是「不会怎样」，那就别用。",
  "pack.cal.life.tip.stress.title": "休息和活动一样重要",
  "pack.cal.life.tip.stress.body": "一直处于警戒状态的狗，是在从内部消耗自己的身体。不被打扰的睡眠、可预期的一天，以及运动后的安静，都不是懒惰——那是身体用来自我修复的时间。",
  "pack.cal.life.tip.protocol.title": "用协议代替惊慌地跑去看兽医",
  "pack.cal.life.tip.protocol.body": "驱虫、粪便检验和血液检查在日历中都有各自的窗口。一只每年检查两次血液的狗，不是在被治疗——而是在被提前预防。",
  "pack.cal.life.tip.joints.title": "关节问题要在开始疼之前解决",
  "pack.cal.life.tip.joints.body": "你的狗现在已经进入老年阶段。关节疗程在日历中的窗口从十一月开始——不是因为它瘸了，而是为了让它永远不必瘸。",
