  "pack.hero.popStatusEyebrow": "状态",
  "pack.hero.popPawtner1": "Pawtner 是你在犬群中的身份——你是你为之创建 HEROGLYPH 的那只狗的同伴。没有 heroglyph，就不是多吉普特人。",
  "pack.hero.rolePack": "犬群",
