  "pack.network.ads.body": "付费广告是一种效率很低的方式，用来寻找新的爱犬人士——而且等于把我们的钱送给大公司。直接奖励这场运动里积极活跃的成员，效果要好得多。只有一个条件：<strong style=\"font-weight:600\">它只有在你真正走出去、把我们介绍给身边的人时才会真正见效</strong> :)",
  "pack.network.ads.header": "为什么用这种方式？",
