  "pack.network.capped.none": "这笔转账没有带来任何奉献值——你的奖励已经追平了你经历过的一切。BONES 仍会照常转过去。<i>金钱能让岁月加倍，却永远无法替代岁月。</i>",
  "pack.network.capped.room": "上限为 <b style=\"color:#2a1608\">{room}</b>——奖励只能追平你已经经历过的部分（目前已有 {lived} 奉献值）。BONES 仍会照常转过去；荣誉会等着那些日子来兑现。",
