  "pack.network.devotionWord": "奉献",
  "pack.network.emptyLine": "这里还没有人——第一个出现的名字，就是你这条线的起点。",
  "pack.network.eyebrow": "DOGYPT 因为有你才能成长",
  "pack.network.generatingLink": "正在生成你的链接……",
  "pack.network.linkFailed": "无法加载你的邀请链接。",
