  "pack.network.groupTheirBrings": "他们带来的人",
  "pack.network.inLine": "在你这条线上",
  "pack.network.info.bones.body": "BONES 是 DOGYPT 的内部货币——一个带点玩味的名字，背后却是真实的东西。狗用骨头来「付钱」；我们也一样。你通过把爱犬人士带进犬群、推动这场运动前进来<b>赚取</b>它们，并在 DOGYPT 内部<b>花掉</b>它们：支持收容所募捐、兑换周边商品，以后还能用来付钱给其他多吉普特人，换取他们创作的东西。<b>{n} BONES = €1。</b>",
  "pack.network.info.bones.cap": "什么是 BONES？",
  "pack.network.info.why.body": "这么大规模的一场运动是买不来的——没有任何预算能像一位多吉普特人接触朋友那样，真正触及一个陌生人。所以犬群把奖励放在影响力真正发生的地方——也就是你这里。当有人通过你的链接加入时，你会获得 <b>{l1} BONES</b>；当他再带来一个人时，你还会再获得 <b>{l2}</b>。每一位传播这个消息的多吉普特人，都不是推销员——他们是传教者，我们尊重这份工作。",
  "pack.network.info.why.cap": "为什么我们要请你这么做",
  "pack.network.intro": "一场运动只有在成员主动传递信息、带来新的人时才会成长。所以我们直接请求你：<strong style=\"color:#2a1608;font-weight:600\">邀请你认识的爱犬人士</strong>。下面就是具体的运作方式。",
