  "onepage.apps.cause.lede": "我们出于对狗的爱，一起打造 DOGYPT——100 % 透明。每位成员都能看到所有收入和支出。",
  "onepage.apps.ainubis.lede": "我们的个性化 AI 导师，对你的狗了如指掌——依托经过验证的书籍、文章和短播客。",
  "onepage.apps.head": "会员资格",
