  "onepage.fin.moreClose": "关闭",
  "onepage.fin.moreBody": "## 救星 Hektor\n\n[[1]]\n\n收养 Hektor 不到一年，我就知道自己的人生再也回不到从前了。经历一次心碎和一段艰难的日子后，**我的狗成了我的救赎**。我把全部的关注和时间都给了它——不是因为我必须这么做，而是因为这让我感到充实。我的每一次冒险，它都摇着尾巴回应，所以直到今天，我们仍一起走遍森林、高山和许多国家。\n\n## 半身像与 Heroglyph\n\n[[2]]\n\n在 3D 打印和扫描刚开始流行的时候，我想到给 Hektor 做一尊半身像。感觉酷极了，我甚至想拿它创业，可扫描仪太贵、事情又太费劲，当时并没有光明的前景。不过 Hektor 的半身像我已经有了，于是我把它的名字刻了上去……然后想：行是行，可叫这个名字的狗多得是。得有点原创的东西，一个只属于它的符号。这个念头让我创造了**专属的 HEROGLYPH**——一个描述 Hektor 一切的符号。我意识到别的狗也能用，于是创造了一整套类似象形文字的符号字母表。我热爱古埃及，把它和狗结合起来，感觉特别高级。\n\n“这门通用语言能把世界各地的爱狗人聚在一起”，这个想法也是在那时诞生的。我脑子里已经有了一幅愿景，它让我多年来夜不能寐。\n\n## 迪拜的法老\n\n[[3]]\n\n我的第一次实战洗礼是一个支线任务——迪拜的法老。我扮成法老去了迪拜世博会，想制造冲击、让人注意到我那个乍一听毫无道理的想法。狗和埃及？**埃及不是猫的地盘吗？**……在世博会上，我“碰巧”站到了一台埃及电视台的摄像机前，他们录下了对我的采访。我在采访中解释说，我穿的不是埃及服装，而是多吉普特服装，并请求他们允许我借用他们的灵感来做我的项目。我不知道他们有没有听懂，但他们说：好 :)\n\n## SNP 英雄之路\n\n[[4]]\n\n2022 年对我来说是个转折点。尽管我性格内向，还是开始为网络拍摄自己，讲述我的想法。目标是建立一个由爱狗人士组成的社群，向他们介绍这个计划。这是极度走出舒适区的一步，但我靠拍摄自己做 Hektor 和我最爱的事来化解它：在山里行走。试点项目是走完斯洛伐克最长、最艰难的长距离步道——斯洛伐克民族起义英雄之路。**我们在 42 天里走了 821 公里**，那是我人生中最美的一章。这场“遛狗”期间，我们为收容所筹款。**我们帮助了 13 家收容所，送去了 2 吨狗粮**。这趟旅程为我们打开了“网络影响力”世界的大门。\n\n从那以后，我们拍摄自己的生活，协助并组织筹款，也在一线帮忙（我们救助猫——家里有两只公猫——和其他动物）。我们还制作内容，向宠物主人科普生活方式和营养——我是自学的，读过几十本书，也有多年的实践经验。我最大的骄傲和最好的广告就是 Hektor，十岁了，依然像年轻的狗一样精力充沛。我的目标是让它活到世界上最长寿的狗的年纪——而且身体健康。\n\n## 跌倒与重来\n\n[[5]]\n\n2023 年我出版了一本关于我们 SNP 之旅的书——除了游记，我还解释了我为什么要做这一切，并第一次更详细地阐述了 DOGYPT 的理念。随后，在把这个想法酝酿多年之后，我放手一搏，把当时攒下的所有钱都付给了一家机构——**超过 2 万欧元**。那家机构本该做一个 heroglyph 生成器。不幸的是，我遇到了不守信用的人，一年后，我既没了钱，也没有生成器。我很颓，不想再创作任何东西。我试过把这个想法带上电视，可没通过海选……2024 年，一位投资人在午餐时告诉我，这个“有趣的项目”大约要花 200 万欧元，这让我有点瘫了。\n\n两年后，AI 出现了。我之前做营销和网页设计，于是决定朝这个方向自学，好自己搭建 DOGYPT。我发现有了 AI，一切真的都有可能，我的创意头脑挣脱了锁链。我拿出最后的积蓄，辞了职，从 2026 年 3 月起，我每天都在努力把这个想法变成现实。我和我的 AI 智能体们每周大约工作 200 小时，不保证成功。**一个被称作做梦者的、着了魔的 33 岁男人**决定把整个人生献给这个使命……我想把所有爱狗的人团结成一个社群，让它有力量去帮助需要帮助的狗，同时和自己的狗过上更好、更美的生活。我也有难熬的日子，所以我常常待在树林里。我对自己说，这是电影里大团圆结局前最痛的那一段 :) 自从走上这条路，生活不断给我带来各种征兆和巧合，让我心底明白一切都在该在的位置，而它“爆发”的时刻正在慢慢临近。有时**一根火柴真的就足以点燃整片森林**……也许你就是那根火柴。\n\n## 人性\n\n[[6]]\n\n整个想法酝酿了很多年，几乎没什么进展，因为它太烧钱，也因为对我来说最宝贵的时间过去是、现在仍是和 Hektor 在森林里度过的时光，远离文明，享受旅行和远行。我不知道还有什么比这更美，其他一切都是次要的。不过，我真的很享受做 DOGYPT，因为它是还不存在的东西，有着改变狗和人的世界的巨大潜力。多年来我一直坚信自己喜欢动物胜过喜欢人，直到今天依然如此，但我爱那些散发着人性与善良、像我一样爱自己动物的人。这些人现在是我们的粉丝，其中许多还是很棒的朋友（社交媒体上有超过 4 万人关注我们）。我意识到，只有这样的人才能理解并支持这个想法，没有他们我们永远做不成。所以：**我不喜欢人类，但我热爱人性和动物——尤其是狗！** :)\n\n## 一起来做吧\n\n前方等待我们的是什么，我不知道，但我非常享受这段旅程。创造、发展和建设需要很多钱，更需要时间，而时间我愿意毫不犹豫地付出。如果你是一位心地善良的慈善家，想投资这个想法，我会非常高兴！\n\n所以，如果你读到这里，还没有在小声嘀咕“他正常吗？”，你可以通过加入这个项目来支持我们——**花象征性的 11 欧元创建一个 heroglyph**（其中 1 欧元是我的工资）。要成为百万富翁，我需要网络里有一百万只狗，这是第一个里程碑 :) 如果你没有狗，或者已经是成员，任何宣传、人脉或分享都对我们有帮助……总之，我们聊聊，一起把它做成。我做这一切，是为了我们——爱狗的人。我乐于接受新想法，也欢迎和愿意参与的人合作。**DOGYPT 不是关于我，而是关于我们所有人。**\n\n让这个故事有力量、有象征意义的，是**站在它背后的那只收容所里的狗**。狗的爱是一种奇迹，是宇宙中两个生命之间持续最久的爱——它值得在我们的社会中拥有一席之地，值得拥有永恒的传承：DOGYPT。\n\n感谢你抽出时间。\nMatej 和 Hekthor I.",
