  "onepage.hbook.0.glyph": "Hekthor 的 heroglyph",
  "onepage.hbook.0.sub": "Hekthor · 狗 #1",
  "onepage.hbook.0.cap": "镜子",
  "onepage.hbook.1.ini": "生",
  "onepage.hbook.1.lead": "来就没人要。被丢在一个箱子里，它和兄弟们在那里等死。",
  "onepage.hbook.1.txt": "八个小生命来到了收容所。其中七只找到了家，只有一只留了下来——个头最大、脾气也最大的那一只。一年后，纯属偶然，它遇到了从没打算养狗的 Matej。火花迸发，自 2017 年 6 月起，他们便一起走过人生。",
  "onepage.hbook.1.cap": "箱子里的八只",
  "onepage.hbook.2.ini": "它",
  "onepage.hbook.2.lead": "救了一个人的命。它出现在那个人最艰难的季节。",
  "onepage.hbook.2.txt": "在最黑暗的日子里，它是 Matej 的锚——把他从阴暗的念头里、从房间里拉出来，带进大自然。先是附近的街道，然后是森林和高山。他们走遍了整个斯洛伐克（820 公里），也在欧洲各地自驾旅行。冒险和路上的自由生活把他们紧紧联系在一起。",
  "onepage.hbook.2.cap": "从办公室走向世界",
  "onepage.hbook.3.ini": "它",
  "onepage.hbook.3.lead": "纯净的灵魂带来了一个愿景：为爱狗人士发起一场全球运动。",
  "onepage.hbook.3.txt": "和狗一起生活，是每个人生命中最美的一章。爱狗的人是另一种人——他们一次又一次地遇到同样特别的难题，又被对狗的爱联系在一起。要是这个故事能变得有用呢？",
  "onepage.hbook.3.cap": "愿景诞生",
  "onepage.hbook.4.ini": "十",
  "onepage.hbook.4.lead": "个美好的年头已在身后，前面至少还有十年！",
  "onepage.hbook.4.txt": "Hekthor 启发 Matej 去了解关于狗的一切——心理、训练、运动，最重要的是长寿。所有这些知识都会在 DOGYPT 里为大家所用：不是又一个花哨的社交网络，而是有意义内容的社交网络。而这一切，都因为一只“普通”的收容所里的狗。",
  "onepage.hbook.4.cap": "创始成员 #1",
  "onepage.hbook.5.ini": "今",
  "onepage.hbook.5.lead": "天它生活在斯洛伐克——在森林里、高山上和湖边。",
  "onepage.hbook.5.txt": "从水里叼回东西是它最大的爱好。它状态绝佳、聪明、谦逊，是任何人都想要的最好伙伴。我们不在外面的时候，它就在家里看守两只公猫 Gary 和 Yby——是它从街头救下的。",
  "onepage.hbook.5.cap": "家的守护者",
